def extract(src: str, name: str) -> str:
    i = src.find(name)
    if i < 0:
        raise SystemExit("tidak ditemukan: " + name)
    arrow = src.find("=>{", i)
    j = src.find("{", arrow)
    depth, k = 0, j
    quote, esc = None, False
    while k < len(src):
        c = src[k]
        if quote:
            if esc:
                esc = False
            elif c == "\\":
                esc = True
            elif c == quote:
                quote = None
            k += 1
            continue
        if c in ('"', "'", "`"):
            quote = c
        elif c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                return src[i:k + 1]
        k += 1
    raise SystemExit("tidak ada penutup: " + name)


