def patch(src: str) -> str:
    src = src.replace(extract(src, "Jg=({currentTab"), NEW_SIDEBAR, 1)
    print("  sidebar kiri + mobile bottom nav dipasang")
    src = src.replace(extract(src, "hb=({serviceRepo"), NEW_DASH, 1)
    print("  dashboard Bento dipasang")

    # main butuh margin kiri di desktop & padding bawah di mobile
    old_main = 'n.jsxs("main",{className:"flex-1",children:['
    if old_main in src:
        src = src.replace(old_main, 'n.jsxs("main",{className:"flex-1 app-main pb-20 md:pb-0",children:[', 1)
        print("  area konten disesuaikan untuk sidebar")

    # tab garansi & backup
    marker = 'M==="laporan"&&n.jsx(Sb,{financeRepo:m}),'
    extra = 'M==="garansi"&&n.jsx(Eb,{warrantyRepo:b}),M==="backup"&&n.jsx(_b,{isOpen:!0,onClose:()=>U("beranda"),backupService:g,onRestoreCompleted:T}),'
    if marker in src and 'M==="garansi"&&n.jsx(Eb' not in src:
        src = src.replace(marker, marker + extra, 1)
        print("  tab Garansi & Backup ditambahkan")
    return src


